sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') { // If None is selected in outcome hiding the fields
        onLoadHidemaker(false); //  Hide for maker Hiding SWIFT Linking Reference ID and Select SWIFT Linking Reference ID - Left Side Fields on the Task form
        onLoadShowChecker(true); // show for checker if field not empty
        return;
    }


    try {

        var trdTaskType = g_form.getValue('trade_task_type'); //Check if Maker or Checker
        var trdSourceSsytem = g_scratchpad.trdSourceSystem;
        var taskState = g_form.getValue('state').toString();

        if ((trdTaskType.toString() == 'Maker') && (trdSourceSsytem.toString() != 'GHSS') && (trdSourceSsytem.toString() != 'GCS') && ((taskState == '1') || (taskState == '2'))) { //Check if Maker or Checker

            var checkOutcome = new GlideAjax('x_hsb11_mss_c_proc.hsbcTranSwiftLinkingPassive');
            checkOutcome.addParam('sysparm_name', 'validateOutcome');
            checkOutcome.addParam('sysparm_tskOutcome', newValue);
            checkOutcome.getXMLAnswer(handleResponse);
        }
    } catch (error) {

    }

    function handleResponse(response) {
        var taskShortDesc = g_form.getValue('short_description').toString();
        var trdOwningBsuiness = g_scratchpad.owningBus.toString();

        if (response == 'Mandate') { //mandate outcomes change in propertiy  = custody_Task_outcomes_mandate_check
            showForMandatoryOutcomes(true);
        } else if (response == 'NonMandate') { //non-mandate outcomes change in propertiy  =x_hsb11_mss_c_proc.custody_Task_outcomes_non_mandate_check
            showForNonMandatoryOutcomes();
        } else if (((trdOwningBsuiness.indexOf('UK') > -1) || (trdOwningBsuiness.indexOf('EU') > -1)) && (newValue.toString() == 'Rejected NEWM SWIFT to Not be Processed') && (taskShortDesc.indexOf('MT544-7') > -1)) {
            showForNonMandatoryOutcomes();
        } else { // any other outcome for which the fields (swift_linking_reference_id and tran_reference_for_swift_linking) should not be visible
            showForMandatoryOutcomes(false);

        }
    }



    function onLoadHidemaker(param) {
        var tskType = g_form.getValue('trade_task_type').toString(); //Check if Maker or Checker
        var taskState = g_form.getValue('state').toString();
        var trdSourceSsytem = g_scratchpad.trdSourceSystem.toString();


        if (((taskState == '1') || (taskState == '2')) && (tskType == 'Maker')) { // hiding all the fields if task status is active
            g_form.setMandatory('swift_linking_reference_id', param);
            g_form.setMandatory('tran_reference_for_swift_linking', param);
            g_form.setDisplay('swift_linking_reference_id', param);
            g_form.setDisplay('tran_reference_for_swift_linking', param);

            //Hiding SWIFT Linking Reference ID and Select SWIFT Linking Reference ID - Left Side Fields on the Task form
            g_form.setMandatory('swift_linking_reference', param);
            g_form.setMandatory('swift_linking_reference_id_ref', param);
            g_form.setDisplay('swift_linking_reference', param);
            g_form.setDisplay('swift_linking_reference_id_ref', param);
        }

        if ((trdSourceSsytem == 'GHSS') || (trdSourceSsytem == 'GCS')) { // hiding the fields for non swift trades
            hideFornonSwiftTrades(false);
        }

    }


    function onLoadShowChecker(param) {
        var taskState = g_form.getValue('state').toString();
        // Function for displaying fields for checker task
        if ((taskState != '1') || (taskState != '2')) {
            g_form.setDisplay('swift_linking_reference_id', false); // hiding the swift_linking_reference_id after completed

            //hiding other three swift fields if they are empty

            if (g_form.getValue('swift_linking_reference') != '') {
                g_form.setDisplay('swift_linking_reference', param);

            } else {
                g_form.setDisplay('swift_linking_reference', false);
            }

            if (g_form.getValue('swift_linking_reference_id_ref') != '') {
                g_form.setDisplay('swift_linking_reference_id_ref', param);
            } else {
                g_form.setDisplay('swift_linking_reference_id_ref', false);
            }

            if (g_form.getValue('tran_reference_for_swift_linking') != '') {
                g_form.setDisplay('tran_reference_for_swift_linking', param);
            } else {
                g_form.setDisplay('tran_reference_for_swift_linking', false);
            }

        }
    }


    function showForMandatoryOutcomes(param) {
        g_form.setMandatory('swift_linking_reference_id', param);
        g_form.setMandatory('tran_reference_for_swift_linking', param);
        g_form.setDisplay('swift_linking_reference_id', param);
        g_form.setDisplay('tran_reference_for_swift_linking', param);
    }

    function showForNonMandatoryOutcomes() {
        g_form.setMandatory('swift_linking_reference_id', false);
        g_form.setMandatory('tran_reference_for_swift_linking', false);
        g_form.setDisplay('swift_linking_reference_id', true);
        g_form.setDisplay('tran_reference_for_swift_linking', true);
    }

    function hideFornonSwiftTrades(param) {
        g_form.setMandatory('swift_linking_reference_id', param);
        g_form.setMandatory('tran_reference_for_swift_linking', param);
        g_form.setDisplay('swift_linking_reference_id', param);
        g_form.setDisplay('tran_reference_for_swift_linking', param);
        g_form.setMandatory('swift_linking_reference', param);
        g_form.setDisplay('swift_linking_reference', param);

    }




}
